code_templates.solution_code:
package main

import "fmt"

func main() {
	menu := [6]string{"Water", "Burger", "Cake", "Soup", "Soda", "Fries"}
	var x int
	fmt.Scanln(&x)
	if x > 5 || x < 0 {
		fmt.Println("无效选择")
	} else {
		fmt.Println(menu[x])
	}
}
